// Responsibility: the text of the files `solarsql build` writes: the
// generated file of a module, its stub before the first build, and the
// migration bundle a Durable Object imports.
// Boundary: no analysis and no file system. build.ts decides what goes in
// and where it goes.
import type { Analysis, Brand } from "./typegen.ts";

export const GENERATED_FILE = "solarsql.generated.ts";

export type GeneratedInput = {
  library: string;
  module: string;
  ownBrands: readonly Brand[];
  importedBrands: readonly { specifier: string; names: readonly string[] }[];
  entries: readonly { key: string; analysis: Analysis }[];
};

// The second line answers the question a reader has when a type is
// missing: which command rewrites this file.
const header = "// Generated by solarsql build. Do not edit.\n// After a change to a statement, run `npx solarsql build`, and this file follows.";

export function emitStub(library: string): string {
  return [
    header,
    "// This stub exists so the module imports before the first build.",
    `import type { Meta } from ${JSON.stringify(library)};`,
    "",
    "export type Generated = {};",
    "export const generated: Meta<Generated> = {};",
    "",
  ].join("\n");
}

export function emitGenerated(input: GeneratedInput): string {
  const lines: string[] = [header, `// Module ${input.module}.`];
  // Import only what the file uses, so a project with noUnusedLocals compiles.
  const names = ["Meta"];
  if (input.ownBrands.length > 0) names.unshift("Id");
  if (input.entries.some((e) => e.analysis.params.some((p) => p.type === "SqlValue"))) names.push("SqlValue");
  lines.push(`import type { ${names.join(", ")} } from ${JSON.stringify(input.library)};`);
  for (const imp of input.importedBrands) {
    lines.push(`import type { ${[...imp.names].sort().join(", ")} } from ${JSON.stringify(imp.specifier)};`);
  }
  lines.push("");
  for (const b of input.ownBrands) {
    lines.push(`// The id of a row of ${b.table}.`);
    lines.push(`export type ${b.typeName} = Id<${JSON.stringify(b.table)}>;`);
  }
  if (input.ownBrands.length > 0) lines.push("");
  lines.push("export type Generated = {");
  for (const { key, analysis } of input.entries) {
    if (analysis.doc) lines.push(`  /** ${analysis.doc.replace(/\*\//g, "* /").replace(/\n/g, " ")} */`);
    lines.push(`  ${JSON.stringify(key)}: {`);
    lines.push(`    params: ${object(analysis.params.map((p) => `${ident(p.name)}: ${p.type}`))};`);
    lines.push(`    row: ${object(analysis.columns.map((c) => `${ident(c.name)}: ${c.type}`))};`);
    lines.push("  };");
  }
  lines.push("};");
  lines.push("");
  lines.push("export const generated: Meta<Generated> = {");
  for (const { key, analysis } of input.entries) {
    const params = analysis.params.map((p) => JSON.stringify(p.name)).join(", ");
    const encode = analysis.params.filter((p) => p.encode).map((p) => JSON.stringify(p.name)).join(", ");
    const json = analysis.columns.filter((c) => c.json).map((c) => JSON.stringify(c.name)).join(", ");
    lines.push(`  ${JSON.stringify(key)}: { params: [${params}], encode: [${encode}], json: [${json}] },`);
  }
  lines.push("};");
  lines.push("");
  return lines.join("\n");
}

function object(fields: readonly string[]): string {
  return fields.length === 0 ? "{}" : `{ ${fields.join("; ")} }`;
}

function ident(name: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : JSON.stringify(name);
}

export function emitMigrationsIndex(files: readonly { name: string; sql: string }[]): string {
  const lines: string[] = [header, "// The migration files, for a Durable Object to apply with migrate().", ""];
  lines.push("export const migrations = [");
  for (const f of files) lines.push(`  { name: ${JSON.stringify(f.name)}, sql: ${JSON.stringify(f.sql)} },`);
  lines.push("] as const;");
  lines.push("");
  return lines.join("\n");
}
